CREATE OR REPLACE TABLE `${dataset}.candidate_filter_decisions` PARTITION BY observed_day CLUSTER BY document_id AS WITH
  complete_labels AS
  (SELECT
     r.document_id,
     r.observed_day,
     r.raw_revision_sha256,
     ARRAY
     (SELECT DISTINCT normalized_label
      FROM
        (SELECT TRIM(REGEXP_REPLACE(NORMALIZE_AND_CASEFOLD(label, NFKC), r'[\s\p{Z}\x{0085}\x{001C}-\x{001F}]+', ' ')) AS normalized_label
         FROM UNNEST(p.p.themes) AS label)
      WHERE normalized_label!=''
      ORDER BY normalized_label) AS themes
   FROM `${dataset}.unfiltered_candidate_representatives` AS r
   JOIN `${dataset}.parsed_observations` AS p ON p.raw_revision_sha256=r.raw_revision_sha256),
  evaluated AS
  (SELECT
     document_id,
     observed_day,
     raw_revision_sha256,
     ARRAY_LENGTH(themes) AS full_theme_count,
     ARRAY_CONCAT(IF((EXISTS
                        (SELECT 1
                         FROM UNNEST(themes) AS feature
                         WHERE feature IN ("econ_centralbank", "econ_inflation", "econ_interest_rates", "epu_cats_monetary_policy"))),["D01"],ARRAY<STRING>[]), IF((EXISTS
                                                                                                                                                                      (SELECT 1
                                                                                                                                                                       FROM UNNEST(themes) AS feature
                                                                                                                                                                       WHERE feature IN ("econ_cost_of_living", "econ_housing_prices", "unemployment", "wb_471_economic_growth"))),["D02"],ARRAY<STRING>[]), IF((EXISTS
                                                                                                                                                                                                                                                                                                                   (SELECT 1
                                                                                                                                                                                                                                                                                                                    FROM UNNEST(themes) AS feature
                                                                                                                                                                                                                                                                                                                    WHERE feature IN ("econ_budget_deficit", "econ_taxation", "epu_cats_fiscal_policy", "wb_445_fiscal_policy"))),["D03"],ARRAY<STRING>[]), IF((EXISTS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  (SELECT 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                   FROM UNNEST(themes) AS feature
                                                                                                                                                                                                                                                                                                                                                                                                                                                                   WHERE feature IN ("econ_currency_exchange_rate", "econ_freetrade", "econ_trade_dispute", "wb_2575_trade_policy_and_investment_agreements", "wb_775_trade_policy_and_integration"))),["D04"],ARRAY<STRING>[]), IF((EXISTS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       (SELECT 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        FROM UNNEST(themes) AS feature
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        WHERE feature IN ("econ_earningsreport", "econ_stockmarket", "epu_cats_financial_regulation", "wb_332_capital_markets"))),["D05"],ARRAY<STRING>[]), IF((EXISTS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  (SELECT 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   FROM UNNEST(themes) AS feature
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   WHERE feature IN ("epu_cats_sovereign_debt_currency_crises", "wb_1098_monetary_and_financial_stability", "wb_1245_financial_vulnerability_and_risks"))),["D06"],ARRAY<STRING>[]), IF((EXISTS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           (SELECT 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            FROM UNNEST(themes) AS feature
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            WHERE feature IN ("econ_oilprice", "wb_539_oil_and_gas_policy_strategy_and_institutions"))),["D07"],ARRAY<STRING>[]), IF((EXISTS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        (SELECT 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         FROM UNNEST(themes) AS feature
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         WHERE feature IN ("blockade", "ceasefire", "sanctions"))),["D08"],ARRAY<STRING>[]), IF((EXISTS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   (SELECT 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    FROM UNNEST(themes) AS feature
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    WHERE feature IN ("health_pandemic", "wb_2167_pandemics"))),["D09"],ARRAY<STRING>[]), IF((EXISTS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                (SELECT 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 FROM UNNEST(themes) AS feature
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 WHERE feature IN ("econ_bankruptcy")))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             AND (EXISTS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    (SELECT 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     FROM UNNEST(themes) AS feature
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     WHERE feature IN ("wb_1234_banking_institutions", "wb_317_bank_regulation_and_supervision", "wb_318_financial_architecture_and_banking"))),["C01"],ARRAY<STRING>[]), IF((EXISTS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                (SELECT 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 FROM UNNEST(themes) AS feature
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 WHERE feature IN ("armedconflict", "maritime_incident", "natural_disaster", "negotiations", "political_turmoil", "wb_2480_post_conflict_reconstruction", "wb_2482_reconciliation")))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             AND (EXISTS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    (SELECT 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     FROM UNNEST(themes) AS feature
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     WHERE feature IN ("env_naturalgas", "env_oil", "wb_167_ports", "wb_2299_pipelines", "wb_793_transport_and_logistics_services"))),["C02"],ARRAY<STRING>[]), IF((EXISTS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      (SELECT 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       FROM UNNEST(themes) AS feature
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       WHERE feature IN ("strike")))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   AND (EXISTS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          (SELECT 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           FROM UNNEST(themes) AS feature
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           WHERE feature IN ("wb_1281_manufacturing", "wb_167_ports", "wb_2299_pipelines", "wb_508_power_systems", "wb_793_transport_and_logistics_services"))),["C03"],ARRAY<STRING>[]), IF((EXISTS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                (SELECT 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 FROM UNNEST(themes) AS feature
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 WHERE feature IN ("crisislex_t04_infrastructure", "cyber_attack", "natural_disaster", "power_outage")))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             AND (EXISTS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    (SELECT 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     FROM UNNEST(themes) AS feature
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     WHERE feature IN ("env_naturalgas", "env_oil", "wb_1234_banking_institutions", "wb_1281_manufacturing", "wb_167_ports", "wb_2299_pipelines", "wb_317_bank_regulation_and_supervision", "wb_318_financial_architecture_and_banking", "wb_508_power_systems", "wb_793_transport_and_logistics_services"))),["C04"],ARRAY<STRING>[]), IF((EXISTS
